#include <bits/stdc++.h>
using namespace std;

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i) res *= i;
    return res;
}

long long A(int n, int k) {
    return factorial(n) / factorial(n - k);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    if (n == 1) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> z(1, 1);
    long long aaa = 0;
    for (int i = 2; i <= n; ++i) {
        int size = i * i / 2;
        vector<long long> nz(size, 0);
        for (int j = 0; j < (int)z.size(); ++j) {
            for (int k = 0; k < i; ++k) {
                if (z[j] > 0) {
                    int idx = i - k - 1 + j;
                    if (idx >= 0 && idx < size) {
                        nz[idx] += z[j];
                    }
                }
            }
        }
        vector<long long> d(z.size() + 1, 0);
        for (int w = (int)z.size() - 1; w >= 0; --w) {
            d[w] = (d[w + 1] + z[w]) % mod;
        }
        vector<long long> e(d.size() + 1, 0);
        vector<long long> f(d.size() + 1, 0);
        for (size_t w = 0; w + 1 < e.size(); ++w) {
            e[w + 1] = (e[w] + d[w]) % mod;
            f[w + 1] = (f[w] - (long long)w * d[w]) % mod;
        }
        long long bbb = 0;
        for (size_t jj = 0; jj < z.size(); ++jj) {
            long long ccc = 0;
            int L = jj + 2;
            int R = min((int)z.size() - 1, i + (int)jj);
            if (R >= L) {
                long long delta_e = (e[R + 1] - e[L]) % mod;
                long long delta_f = (f[R + 1] - f[L]) % mod;
                ccc = (ccc + (delta_e * (i + 1 + (int)jj) + delta_f) % mod) % mod;
            }
            bbb = (bbb + ccc * z[jj]) % mod;
        }
        aaa = (aaa + bbb * A(n, n - i)) % mod;
        z = nz;
    }
    cout << (aaa % mod + mod) % mod << "\n";
    return 0;
}

